require_once __DIR__.'/includes/db.php';require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/permissions.php';require_once __DIR__.'/includes/icons.php';require_once __DIR__.'/includes/novedades_semanales_common.php';
auth_require();permissions_require_menu('novedades_semanales_comparativa');$cfg=require __DIR__.'/config.php';date_default_timezone_set($cfg['app']['tz']??'UTC');$APP_USER=auth_user();$APP_ROLE=auth_es_admin()?'Administrador':'Operador';$ACTIVE='novedades_semanales_comparativa';
$db=clear_db();$ready=ns_module_ready($db);$reportReady=$ready&&ns_report_ready($db);$today=new DateTimeImmutable('now');$prefs=ns_preferences();$period=ns_period($_GET,$today,$prefs);$chartType=ns_chart_type($_GET['grafico']??($prefs['comparison_chart']??'line'),'line');$chartPalette=(string)($_GET['paleta']??($prefs['comparison_palette']??'blues'));if(!in_array($chartPalette,['blues','multicolor'],true))$chartPalette='blues';
$type=ns_clean($_GET['tipo_instalacion']??'',30);if($type!==''&&!array_key_exists($type,ns_type_options()))$type='';$installation=ns_clean($_GET['instalacion']??'',180);$rawTags=ns_clean($_GET['tags']??'',900);$tags=[];foreach(preg_split('/[,;\r\n]+/',$rawTags) as $tag){$tag=ns_clean($tag,255);if($tag!==''&&!in_array($tag,$tags,true))$tags[]=$tag;if(count($tags)>=5)break;}
$weekStarts=[];for($i=0;$i<$period['weeks'];$i++)$weekStarts[]=$period['from']->modify('+'.($i*7).' days');$series=[];$topTags=[];$updated='';
if($ready){$conditions=['SEMANA_DESDE>=CONVERT(date,?,23)','SEMANA_DESDE<=CONVERT(date,?,23)'];$params=[$period['from_value'],$period['to_value']];if($type!==''){$conditions[]='TIPO_INSTALACION=?';$params[]=$type;}if($installation!==''){$conditions[]='INSTALACION LIKE ?';$params[]='%'.$installation.'%';}if($tags){$ph=implode(',',array_fill(0,count($tags),'?'));$conditions[]="TAG IN ($ph)";foreach($tags as $tag)$params[]=$tag;}$group=$tags?'SEMANA_DESDE,TAG':'SEMANA_DESDE';$select=$tags?',TAG':'';$data=$db->all("SELECT CONVERT(varchar(10),SEMANA_DESDE,23) SEMANA_DESDE$select,SUM(TOTAL_ALARMAS) TOTAL FROM dbo.CLEAR_NOVEDADES_SEMANALES_CACHE WHERE ".implode(' AND ',$conditions)." GROUP BY $group ORDER BY SEMANA_DESDE",$params);$map=[];foreach($data as $row){$key=(string)ns_value($row,'SEMANA_DESDE');$name=$tags?(string)ns_value($row,'TAG'):'Total de alarmas';$map[$name][$key]=(int)ns_value($row,'TOTAL',0);}$names=$tags?$tags:['Total de alarmas'];foreach($names as $name){$values=[];foreach($weekStarts as $start)$values[]=(int)($map[$name][$start->format('Y-m-d')]??0);$series[]=['label'=>$name,'values'=>$values];}$topTags=$db->all("SELECT TOP 30 TAG,SUM(TOTAL_ALARMAS) TOTAL FROM dbo.CLEAR_NOVEDADES_SEMANALES_CACHE WHERE SEMANA_DESDE BETWEEN CONVERT(date,?,23) AND CONVERT(date,?,23) GROUP BY TAG ORDER BY SUM(TOTAL_ALARMAS) DESC",[$period['from_value'],$period['to_value']]);$updated=(string)$db->scalar("SELECT CONVERT(varchar(19),MAX(FECHA_ACTUALIZACION),120) FROM dbo.CLEAR_NOVEDADES_SEMANALES_CACHE WHERE SEMANA_DESDE BETWEEN CONVERT(date,?,23) AND CONVERT(date,?,23)",[$period['from_value'],$period['to_value']]);}
$labels=[];$dates=[];foreach($weekStarts as $start){$labels[]='Sem. '.$start->modify('+6 days')->format('W');$dates[]=$start->format('Y-m-d');}$comparison=['labels'=>$labels,'dates'=>$dates,'series'=>$series,'type'=>$chartType,'palette'=>$chartPalette,'trendline'=>$chartType!=='doughnut'];$chartPayload=['kind'=>'chart','chart_type'=>$chartType,'palette'=>$chartPalette,'axis_label'=>'Semana','unit'=>'alarmas','labels'=>$labels,'datasets'=>$series,'trendline'=>$chartType!=='doughnut','context'=>$chartType==='doughnut'?'Totales del período.':'Incluye línea de tendencia lineal.'];
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Comparativa · Novedades semanales</title><link rel="stylesheet" href="assets/css/app.css?v=20260826-ns3"><link rel="stylesheet" href="assets/css/novedades_semanales.css?v=20260826-report-common-1"></head><body><div class="app"><?php include __DIR__.'/includes/sidebar.php'; ?><main class="main"><?php include __DIR__.'/includes/topbar.php'; ?>
<div class="page__head nsHead"><div><h1 class="page__title">Comparativa semanal</h1><div class="page__sub">Comparación por período, instalación y hasta cinco TAG, con gráfico configurable y valores visibles.</div></div><div class="page__live"><span class="dot"></span><?php echo $ready?'Datos resumidos':'Requiere instalación'; ?></div></div><?php ns_render_module_nav($ACTIVE); ?>
<?php if(!$ready):ns_render_not_installed();else: ?><form class="nsToolbar" method="get" id="nsComparisonForm"><label class="nsControl"><span>Semana desde</span><input type="date" name="desde" value="<?php echo h($period['from_value']); ?>"></label><label class="nsControl"><span>Semana hasta</span><input type="date" name="hasta" value="<?php echo h($period['to_value']); ?>"></label><label class="nsControl"><span>Tipo</span><select name="tipo_instalacion"><option value="">Todos</option><?php foreach(ns_type_options() as $v=>$l): ?><option value="<?php echo h($v); ?>" <?php echo $type===$v?'selected':''; ?>><?php echo h($l); ?></option><?php endforeach; ?></select></label><label class="nsControl"><span>Instalación</span><input name="instalacion" value="<?php echo h($installation); ?>" placeholder="Todas"></label><label class="nsControl nsControl--wide"><span>TAG a comparar (máximo 5)</span><input name="tags" list="nsTopTags" value="<?php echo h(implode(', ',$tags)); ?>" placeholder="Separados por coma; vacío muestra total"><datalist id="nsTopTags"><?php foreach($topTags as $row): ?><option value="<?php echo h(ns_value($row,'TAG')); ?>"><?php endforeach; ?></datalist></label><label class="nsControl"><span>Gráfico</span><select name="grafico" data-ns-chart-type data-ns-preference="comparison_chart"><option value="line" <?php echo $chartType==='line'?'selected':''; ?>>Líneas</option><option value="bar" <?php echo $chartType==='bar'?'selected':''; ?>>Barras</option><option value="doughnut" <?php echo $chartType==='doughnut'?'selected':''; ?>>Dona</option></select></label><label class="nsControl"><span>Paleta</span><select name="paleta" data-ns-chart-palette data-ns-preference="comparison_palette"><option value="blues" <?php echo $chartPalette==='blues'?'selected':''; ?>>Azules</option><option value="multicolor" <?php echo $chartPalette==='multicolor'?'selected':''; ?>>Multicolor</option></select></label><input type="hidden" data-ns-preference="period_weeks" value="<?php echo (int)$period['weeks']; ?>"><button class="nsButton" type="submit">Comparar</button><a class="nsButton is-secondary" href="novedades_semanales_export.php?vista=comparativa&amp;<?php echo h(ns_query_string()); ?>"><?php echo icon('download'); ?> Excel</a><button class="nsButton is-secondary" type="button" data-ns-save-preferences>Guardar preferencias</button><a class="nsButton is-secondary" href="novedades_semanales_reporte.php">Reporte <span class="nsReportCount" data-ns-report-count hidden>0</span></a></form>
<section class="nsCards"><article class="nsCard nsCard--full"><div class="nsCard__head"><div><h2>Semanas vs. semanas</h2><p><?php echo h(ns_period_label($period)); ?> · actualizada <?php echo h($updated?:'sin datos'); ?>. <?php echo $chartType==='doughnut'?'La dona muestra los totales del período.':'La línea punteada indica la tendencia.'; ?></p></div><div class="nsChartControls"><?php if($reportReady)echo ns_report_pick(ns_report_key('comparativa',[$period['from_value'],$period['to_value'],$type,$installation,$tags,$chartType,$chartPalette]),'chart','Comparativa semanal · '.ns_period_label($period),$chartPayload); ?></div></div><div class="nsCard__body"><div class="nsChartBox" style="height:350px"><canvas id="nsComparisonChart"></canvas></div></div></article></section>
<section class="nsTableCard"><div class="nsTableHead"><div><h2>Valores exactos</h2><p>Orden y búsqueda local por cada columna.</p></div></div><div class="tablescroll"><table class="grid nsTable" id="nsComparisonTable" style="min-width:1000px"><thead><tr><th>REPORTE</th><th><button class="nsClientSort" data-ns-sort-client data-table="nsComparisonTable" data-column="1">SEMANA</button></th><th><button class="nsClientSort" data-ns-sort-client data-table="nsComparisonTable" data-column="2" data-kind="date">DESDE</button></th><th><button class="nsClientSort" data-ns-sort-client data-table="nsComparisonTable" data-column="3">TIPO</button></th><?php foreach($series as $n=>$item): ?><th><button class="nsClientSort" data-ns-sort-client data-table="nsComparisonTable" data-column="<?php echo 4+$n; ?>" data-kind="number"><?php echo h($item['label']); ?></button></th><?php endforeach; ?><th><button class="nsClientSort" data-ns-sort-client data-table="nsComparisonTable" data-column="<?php echo 4+count($series); ?>" data-kind="number">VARIACIÓN</button></th></tr><tr class="nsFilterRow"><th></th><th><input data-ns-client-filter data-table="nsComparisonTable" data-column="1" placeholder="Semana"></th><th><input data-ns-client-filter data-table="nsComparisonTable" data-column="2" placeholder="Fecha"></th><th><select data-ns-client-filter data-table="nsComparisonTable" data-column="3"><option value="">Todos</option><option value="<?php echo h($type?:'Todos'); ?>"><?php echo h($type?:'Todos'); ?></option></select></th><?php foreach($series as $n=>$item): ?><th><input data-ns-client-filter data-table="nsComparisonTable" data-column="<?php echo 4+$n; ?>" placeholder="Valor"></th><?php endforeach; ?><th><input data-ns-client-filter data-table="nsComparisonTable" data-column="<?php echo 4+count($series); ?>" placeholder="Variación"></th></tr></thead><tbody><?php $previousValue=null;foreach($weekStarts as $index=>$start):$rowTotal=0;foreach($series as $item)$rowTotal+=(int)$item['values'][$index];$delta=$previousValue&&$previousValue>0?(($rowTotal-$previousValue)/$previousValue*100):null;$columns=['Semana'=>ns_week_label($start),'Tipo'=>$type?:'Todos'];foreach($series as $item)$columns[$item['label']]=(int)$item['values'][$index];$columns['Variación']=$delta===null?'—':(($delta>0?'+':'').ns_percent($delta)); ?><tr><td class="nsCheckCell"><?php if($reportReady)echo ns_report_pick(ns_report_key('comparativa-fila',[$start->format('Y-m-d'),$type,$installation,$tags]),'row','Comparativa · '.ns_week_label($start),ns_report_row_payload($columns)); ?></td><td><a href="novedades_semanales_malos_actores.php?desde=<?php echo h($start->format('Y-m-d')); ?>&amp;hasta=<?php echo h($start->format('Y-m-d')); ?>"><b>Semana <?php echo h($start->modify('+6 days')->format('W')); ?></b></a></td><td><?php echo h($start->format('d/m/Y')); ?></td><td><span class="nsType <?php echo h(ns_type_class($type)); ?>"><?php echo h($type?:'Todos'); ?></span></td><?php foreach($series as $item): ?><td data-sort="<?php echo (int)$item['values'][$index]; ?>"><span class="nsTotal"><?php echo ns_num($item['values'][$index]); ?></span></td><?php endforeach; ?><td data-sort="<?php echo $delta===null?0:$delta; ?>"><?php if($delta===null): ?>—<?php else: ?><span class="nsDelta <?php echo $delta>0?'is-worse':($delta<0?'is-better':'is-neutral'); ?>"><?php echo ($delta>0?'+':'').ns_percent($delta); ?></span><?php endif; ?></td></tr><?php $previousValue=$rowTotal;endforeach; ?></tbody></table></div></section>
<?php endif; ?></main></div><?php if($ready): ?><script>window.CLEAR_WEEKLY_NEWS=<?php echo json_encode(['comparison'=>$comparison],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>;</script><script src="assets/js/chart.umd.js"></script><?php endif; ?><script src="assets/js/app.js?v=20260826-ns3"></script><script src="assets/js/novedades_semanales.js?v=20260902-cambio1"></script></body></html>
